pub fn Camera_80029AAC<'a>(
    ctx: &'a Ctx,
    bounds: CameraBounds<'a>,
    transform: CameraTransformState<'a>,
    speed: f64,
) {
    let mut bounds = bounds;
    let mut transform = transform;
    let mut speed = speed;
    let mut globals: CameraUnkGlobals<'a> = null(ctx);
    let mut follow_speed: f64 = 0.0;
    let mut temp_f: f64 = 0.0;
    let mut temp_f4: f64 = 0.0;
    let mut temp_f3: f64 = 0.0;
    let mut delta: f64 = 0.0;
    let mut spread: f64 = 0.0;
    let mut lerp_factor: f64 = 0.0;
    let mut offset_x: f64 = 0.0;
    let mut offset_y: f64 = 0.0;
    if (bounds).total_subjects() != 0_i32 {
        temp_f4 = fp::fsubs((bounds).x_max(), (bounds).x_min());
        temp_f3 = fp::fsubs((bounds).y_max(), (bounds).y_min());
        if temp_f4 > temp_f3 {
            spread = temp_f4;
        } else {
            spread = temp_f3;
        }
    } else {
        spread = 99999.0;
    }
    offset_x = fp::fsubs(
        (transform).target_interest().x(),
        (transform).interest().x(),
    );
    offset_y = fp::fsubs(
        (transform).target_interest().y(),
        (transform).interest().y(),
    );
    globals = fns::cm_803BCCA0(ctx);
    follow_speed = inl_get_follow_speed(ctx, (globals).x38(), spread, globals);
    delta = inl_get_delta(ctx, statics::melee__cm__camera::game_camera(ctx).x2BC());
    lerp_factor = fp::fmuls(delta, (fp::fmuls(follow_speed, speed)));
    if lerp_factor > 1.0 {
        lerp_factor = 1.0;
    } else if lerp_factor < 9.999999747378752e-05_f64 {
        lerp_factor = 9.999999747378752e-05_f64;
    }
    (transform).interest().set_x(fp::fmadds(
        offset_x,
        lerp_factor,
        (transform).interest().x(),
    ));
    (transform).interest().set_y(fp::fmadds(
        offset_y,
        lerp_factor,
        (transform).interest().y(),
    ));
}

